function moyenne(notes) {
  const total = notes.reduce((somme, n) => somme + n, 0);
  return total / notes.length;
}

const doubler = (n) => n * 2;

console.log(moyenne([12, 15, 9])); // 12
console.log(doubler(4));           // 8

const prix = [12, 30, 5, 48];

const ttc = prix.map((p) => p * 1.2);
const chers = prix.filter((p) => p > 20);
const total = prix.reduce((s, p) => s + p, 0);

console.log(ttc, chers, total);

