const prefs = { theme: "sombre", taille: 16 };

localStorage.setItem("prefs", JSON.stringify(prefs));

const brut = localStorage.getItem("prefs");
try {
  const lues = brut ? JSON.parse(brut) : null;
  console.log(lues?.theme);
} catch {
  console.error("Données illisibles : on repart des valeurs par défaut.");
}

